 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let text = "";
+  let i = 0;
+
+  const flush = (): void => {
+    if (text !== "") {
+      tokens.push({ kind: "text", text });
+      text = "";
+    }
+  };
+
+  while (i < template.length) {
+    const open = template.indexOf("{{", i);
+    if (open === -1) {
+      text += template.slice(i);
+      break;
+    }
+    text += template.slice(i, open);
+
+    const raw = template[open + 2] === "{";
+    const closer = raw ? "}}}" : "}}";
+    const start = open + (raw ? 3 : 2);
+    const stop = template.indexOf(closer, start);
+    if (stop === -1) throw new Error("unterminated tag");
+    const body = template.slice(start, stop).trim();
+    i = stop + closer.length;
+
+    flush();
+    if (raw) {
+      tokens.push({ kind: "value", expr: body, raw: true });
+    } else if (/^#if(\s|$)/.test(body)) {
+      tokens.push({ kind: "if", path: body.slice(3).trim() });
+    } else if (body === "else") {
+      tokens.push({ kind: "else" });
+    } else if (body === "/if") {
+      tokens.push({ kind: "end" });
+    } else {
+      tokens.push({ kind: "value", expr: body, raw: false });
+    }
+  }
+  flush();
+  return tokens;
 }
